def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    strong_prev_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                if opp.get('daily_salary', 0) >= DAILY_SALARY:
                    strong_prev_bids.append(b)

    if not alive_opponents:
        return min(budget, 18.0)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = hp <= 3 or no_water >= 2
    pressured = hp <= 5 or no_water >= 1

    top_prev = max(prev_bids) if prev_bids else 0.0
    strong_top = max(strong_prev_bids) if strong_prev_bids else top_prev

    if urgent:
        target = max(72.0, strong_top + 3.0, 78.0 + 30.0 * scarcity)
    elif pressured:
        if strong_top >= 150.0:
            target = 34.0 + 10.0 * scarcity
        else:
            target = max(42.0 + 18.0 * scarcity, strong_top + 2.0)
    else:
        if supply >= 22:
            target = 16.0
        elif supply >= 19:
            target = 22.0 + 6.0 * scarcity
        else:
            if strong_top >= 150.0:
                target = 26.0 + 12.0 * scarcity
            else:
                target = max(30.0 + 14.0 * scarcity, strong_top + 1.5)

    if day >= 8 and hp >= 6 and no_water == 0:
        target *= 0.9

    max_safe = budget
    if not urgent:
        reserve = max(0.0, (10 - day) * 8.0)
        max_safe = max(0.0, budget - reserve)
        if max_safe <= 0:
            max_safe = min(budget, 20.0 + 10.0 * scarcity)

    bid = min(target, budget, max_safe if not urgent else budget)
    if urgent and bid < min(budget, 65.0):
        bid = min(budget, 65.0)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Alive opponents and yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Base pressure from yesterday
    if yesterday_bids:
        sorted_bids = sorted(yesterday_bids)
        # Target to beat likely winner without matching extreme
        # Use 2nd highest if available, else highest
        if len(sorted_bids) >= 2:
            target = sorted_bids[-2]
        else:
            target = sorted_bids[-1]
        # Add a small increment to try to win the marginal allocation
        pressure_bid = target + 3.0
    else:
        pressure_bid = DAILY_SALARY * 0.5

    # Determine risk based on our hp and budget.
    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If we are close to running out, bid aggressively.
    # We don't know exact water->hp dynamics, so use conservative triggers.
    low_hp = hp <= 3.0
    critical = (hp <= 2.0) or (no_water_days >= 2)

    # Supply factor: higher supply reduces need to overbid.
    # Convert supply to a normalized factor in [0,1]
    try:
        norm = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    except Exception:
        norm = 0.5
    if norm < 0.0:
        norm = 0.0
    if norm > 1.0:
        norm = 1.0

    # If supply is higher, we can bid slightly less; if lower, bid more.
    supply_adjust = 1.0 + (0.15 * (1.0 - norm))

    # Strategy:
    # - Safe: bid near pressure_bid but capped by a fraction of budget/salary.
    # - Low hp: bid closer to salary tiers.
    if critical:
        desired = max(DAILY_SALARY * 0.75, pressure_bid * 1.05) * supply_adjust
        cap = budget
    elif low_hp:
        desired = max(DAILY_SALARY * 0.6, pressure_bid * 1.0) * supply_adjust
        cap = budget
    else:
        # We can afford to be slightly under the top bid; aim to beat 2nd-highest.
        desired = max(DAILY_SALARY * 0.45, pressure_bid * 0.98) * supply_adjust
        cap = budget

    # Ensure we don't bid negative or exceed budget.
    if cap <= 0:
        return 0.0

    bid = float(desired)
    if bid < 0.0:
        bid = 0.0
    if bid > cap:
        bid = cap

    # Small safety floor: if budget is enough, bid at least a small amount to avoid ties at 0.
    min_bid = min(cap, DAILY_SALARY * 0.25)
    if bid < min_bid and cap > 1e-9:
        bid = min_bid

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    strong_opponent_ids = ["Alex", "David"]
    strong_alive_opponents = [o for o in alive_opponents if o['agent_id'] in strong_opponent_ids]

    if not strong_alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.3) 

    yesterday_strong_bids = []
    for opp in strong_alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_strong_bids.append(prev['bid'])

    reference_opponent_bid = DAILY_SALARY * 0.85 
    if yesterday_strong_bids:
        reference_opponent_bid = max(yesterday_strong_bids)

    bid_amount = DAILY_SALARY * 0.75 

    if my_hp <= 2:
        bid_amount = DAILY_SALARY * 1.1 
    elif my_hp <= 4:
        bid_amount = DAILY_SALARY * 0.95 
    elif my_hp >= 8:
        bid_amount = DAILY_SALARY * 0.6 

    if reference_opponent_bid > DAILY_SALARY * 0.7:
        bid_amount = max(bid_amount, reference_opponent_bid + 2.0)
    else:
        if my_hp >= 8:
            bid_amount = min(bid_amount, reference_opponent_bid + 5.0) if reference_opponent_bid > 0 else DAILY_SALARY * 0.55
        else:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.7)

    if current_day == EPISODE_DAYS and my_hp > 0:
        return my_budget

    if my_status['no_water_days'] > 0 and my_hp <= 3:
        bid_amount = max(bid_amount, DAILY_SALARY * 1.0)

    final_bid = min(my_budget, bid_amount)
    return max(0.0, final_bid)

